import csv
import io

def summarize_expenses(csv_text):
    totals = {}
    reader = csv.reader(io.StringIO(csv_text))
    header = next(reader, None)
    for row in reader:
        # Skip blank lines (rows with no fields or all empty)
        if not row or all(field.strip() == '' for field in row):
            continue
        # category is index 1, amount is index 2
        if len(row) < 3:
            continue
        cat = row[1].strip().lower()
        raw_amount = row[2].strip()
        if not raw_amount:
            continue
        # Parse amount
        negative = False
        if raw_amount.startswith('(') and raw_amount.endswith(')'):
            negative = True
            raw_amount = raw_amount[1:-1]
        raw_amount = raw_amount.replace('$', '').replace(',', '').strip()
        if not raw_amount:
            continue
        amount = float(raw_amount)
        if negative:
            amount = -amount
        totals[cat] = totals.get(cat, 0) + amount
    # Round to 2 decimals
    return {k: round(v, 2) for k, v in totals.items()}
